-- Run this script in pgAdmin Query Tool after creating database crj_db.
-- Column names are quoted intentionally to preserve the CRJ naming/casing.
CREATE TABLE IF NOT EXISTS "CRJ_Record_Mapping_Details" (
    "Record_Code" VARCHAR(50) PRIMARY KEY,
    "Description" VARCHAR(200) NOT NULL
);

CREATE TABLE IF NOT EXISTS "CRJ_Header" (
    "Record_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Record_Code" VARCHAR(50) NOT NULL REFERENCES "CRJ_Record_Mapping_Details"("Record_Code"),
    "Time_stamp" TIMESTAMP WITHOUT TIME ZONE NOT NULL DEFAULT CURRENT_TIMESTAMP,
    "User_id" VARCHAR(50)
);

CREATE TABLE IF NOT EXISTS "CRJ_Details" (
    "Detail_ID" INTEGER GENERATED BY DEFAULT AS IDENTITY PRIMARY KEY,
    "Record_ID" INTEGER NOT NULL REFERENCES "CRJ_Header"("Record_ID") ON DELETE CASCADE,
    "File_ID" VARCHAR(20),
    "Job_Name" VARCHAR(50),
    "RCVD_DATE_TYPE" VARCHAR(100),
    "Deposit_Date" DATE,
    "Days" INTEGER,
    "Hours" NUMERIC(10,4),
    "Due_Amount" NUMERIC(10,4),
    "Amount_Recd" NUMERIC(10,4),
    "ADJ_Hrs" NUMERIC(10,4),
    "ADJ_Due" NUMERIC(10,4),
    "ADJ_Paid" NUMERIC(10,4),
    "Interest" NUMERIC(10,4),
    "Liq_Damgs" NUMERIC(10,4),
    "Legal_Fees" NUMERIC(10,4),
    "Principal" NUMERIC(10,4),
    "Interest_2" NUMERIC(10,4),
    "Claims" NUMERIC(10,4),
    "Cost" NUMERIC(10,4),
    "Legal" NUMERIC(10,4),
    "Total_Deposit" NUMERIC(10,4),
    "System Difference" NUMERIC(10,4),
    "Employer_No" VARCHAR(50),
    "Employer_Name" VARCHAR(200),
    "Report_Type" VARCHAR(100),
    "Work_Month" VARCHAR(20),
    "Comments" TEXT,
    "Under_Paid" NUMERIC(10,4),
    "SIDE_NOTES" TEXT,
    "BATCHED_BY" VARCHAR(200),
    "BATCHED_BY_DATE" DATE,
    "KEYED_BY" VARCHAR(200),
    "KEYED_BY_DATE" DATE,
    "CHECKED_BY" VARCHAR(200),
    "CHECKED_BY_DATE" DATE
);

INSERT INTO "CRJ_Record_Mapping_Details" ("Record_Code", "Description") VALUES
('WELFARE', 'Welfare CRJ records'),
('HOUSING', 'Housing CRJ records'),
('TRAINING', 'Training CRJ records'),
('LEGAL', 'Legal CRJ records')
ON CONFLICT ("Record_Code") DO NOTHING;

